// OrakoServiceHandler is an implementation of the orako.v1.OrakoService service.
type OrakoServiceHandler interface {
	// --- Directory / routing: the agent matches this against its git history ---
	ListExperts(context.Context, *connect.Request[v1.ListExpertsRequest]) (*connect.Response[v1.ListExpertsResponse], error)
	// --- Conversations (async: Ask returns an id; resume later) ---
	Ask(context.Context, *connect.Request[v1.AskRequest]) (*connect.Response[v1.AskResponse], error)
	GetConversation(context.Context, *connect.Request[v1.GetConversationRequest]) (*connect.Response[v1.GetConversationResponse], error)
	FollowUp(context.Context, *connect.Request[v1.FollowUpRequest]) (*connect.Response[v1.FollowUpResponse], error)
	ResolveConversation(context.Context, *connect.Request[v1.ResolveConversationRequest]) (*connect.Response[v1.ResolveConversationResponse], error)
	// DismissConversation closes an unanswered conversation WITHOUT distilling a
	// KB entry (the asker or a responder gave up on it). Project-member RBAC,
	// not admin. Only an open or answered conversation can be dismissed.
	DismissConversation(context.Context, *connect.Request[v1.DismissConversationRequest]) (*connect.Response[v1.DismissConversationResponse], error)
	// --- Listing (dashboard) ---
	// ListProjects returns the projects the caller is a member of (any role).
	// Caller identity comes from the auth token; no project_id needed.
	ListProjects(context.Context, *connect.Request[v1.ListProjectsRequest]) (*connect.Response[v1.ListProjectsResponse], error)
	// ListConversations returns conversations in a project, newest first.
	// RBAC: the caller's token project must match project_id.
	ListConversations(context.Context, *connect.Request[v1.ListConversationsRequest]) (*connect.Response[v1.ListConversationsResponse], error)
	// ListInbox returns the caller's pending questions: open conversations where
	// the caller is the responder, newest first. Caller identity comes from the
	// token; no member_id field. Backs the dashboard-channel inbox screen.
	ListInbox(context.Context, *connect.Request[v1.ListInboxRequest]) (*connect.Response[v1.ListInboxResponse], error)
	// SearchHistory runs the deterministic (embedding-free) history search over
	// the caller's conversations and returns ranked hits plus a status breakdown
	// for the KPI/facet pills. Backs the dashboard History tab. Scope mirrors
	// ListConversations (org + optional project_ids, archived excluded). An empty
	// query browses the most recent conversations in scope.
	SearchHistory(context.Context, *connect.Request[v1.SearchHistoryRequest]) (*connect.Response[v1.SearchHistoryResponse], error)
	// GetDashboardMetrics returns the org KPI overview (conversations, response
	// rate, median time-to-first-response, current backlog, leaderboards) for the
	// caller's scope over a period. Backs the dashboard that replaces "Get
	// started" once onboarding is complete. Scope mirrors ListConversations.
	GetDashboardMetrics(context.Context, *connect.Request[v1.GetDashboardMetricsRequest]) (*connect.Response[v1.GetDashboardMetricsResponse], error)
	// --- Curated knowledge (decision 2026-07-26) ---
	// ListKnowledgeEntries lists the org's curated knowledge entries (every
	// status), newest first, for the dashboard Knowledge section. Org-scoped —
	// any member may read the team's curated answers. Scope mirrors SearchHistory
	// (org + optional project_ids); org-wide entries (no project) always included.
	ListKnowledgeEntries(context.Context, *connect.Request[v1.ListKnowledgeEntriesRequest]) (*connect.Response[v1.ListKnowledgeEntriesResponse], error)
	// CreateKnowledgeEntry authors one curated entry (org-admin gated). Org +
	// author come from the token, never the request. Searchable via SearchHistory
	// alongside conversation history, attributed to the org.
	CreateKnowledgeEntry(context.Context, *connect.Request[v1.CreateKnowledgeEntryRequest]) (*connect.Response[v1.CreateKnowledgeEntryResponse], error)
	// UpdateKnowledgeEntry rewrites an entry's editable fields (org-admin gated).
	UpdateKnowledgeEntry(context.Context, *connect.Request[v1.UpdateKnowledgeEntryRequest]) (*connect.Response[v1.UpdateKnowledgeEntryResponse], error)
	// MarkKnowledgeStale flags an entry stale so it drops out of search (org-admin
	// gated). Reversible via UpdateKnowledgeEntry with status="active".
	MarkKnowledgeStale(context.Context, *connect.Request[v1.MarkKnowledgeStaleRequest]) (*connect.Response[v1.MarkKnowledgeStaleResponse], error)
	// RevalidateKnowledgeEntry re-confirms a stale entry as current: status back to
	// active + updated_at bumped ("last reviewed"). Org-admin gated.
	RevalidateKnowledgeEntry(context.Context, *connect.Request[v1.RevalidateKnowledgeEntryRequest]) (*connect.Response[v1.RevalidateKnowledgeEntryResponse], error)
	// --- Agent-suggested approval queue (Phase 2, trust gradient) ---
	// ListPendingKnowledge lists the agent-suggested entries awaiting review
	// (source=agent_suggested, status=pending), newest first, for the dashboard's
	// "Pending review" queue. Org-admin gated. Scope mirrors ListKnowledgeEntries.
	ListPendingKnowledge(context.Context, *connect.Request[v1.ListPendingKnowledgeRequest]) (*connect.Response[v1.ListPendingKnowledgeResponse], error)
	// ApproveKnowledgeEntry approves a pending agent-suggested entry → status
	// active (now human-vetted, searchable). Provenance source stays
	// agent_suggested. Org-admin gated.
	ApproveKnowledgeEntry(context.Context, *connect.Request[v1.ApproveKnowledgeEntryRequest]) (*connect.Response[v1.ApproveKnowledgeEntryResponse], error)
	// DismissKnowledgeEntry rejects a pending agent-suggested entry by deleting the
	// row (no 'dismissed' status is kept). Org-admin gated.
	DismissKnowledgeEntry(context.Context, *connect.Request[v1.DismissKnowledgeEntryRequest]) (*connect.Response[v1.DismissKnowledgeEntryResponse], error)
	// PromoteConversationToKnowledge distills a RESOLVED conversation into a curated
	// entry (source=curated, status=active) authored by the promoter, carrying the
	// question, composed answer, and summary/tags/entities. Org-admin gated.
	PromoteConversationToKnowledge(context.Context, *connect.Request[v1.PromoteConversationToKnowledgeRequest]) (*connect.Response[v1.PromoteConversationToKnowledgeResponse], error)
	// --- Member self-service (contact channel) ---
	// GetMember returns the caller's own member record (channel + bindings).
	GetMember(context.Context, *connect.Request[v1.GetMemberRequest]) (*connect.Response[v1.GetMemberResponse], error)
	// UpdateMember updates a member's contact settings (delivery channel,
	// bindings, display name). Default target = the token caller; setting
	// member_id targets another member and is org-admin gated.
	UpdateMember(context.Context, *connect.Request[v1.UpdateMemberRequest]) (*connect.Response[v1.UpdateMemberResponse], error)
	// ListConnectedChannels returns the delivery channels available to the caller:
	// always "dashboard", plus each functional external provider configured for
	// the caller's project. Backs the contact-channel picker (greys out the rest).
	ListConnectedChannels(context.Context, *connect.Request[v1.ListConnectedChannelsRequest]) (*connect.Response[v1.ListConnectedChannelsResponse], error)
	// SetOwnExpertise sets the CALLER's expertise tags (domains) across every
	// project they belong to. Self-scoped and NOT admin-gated: any authenticated
	// member may set their own expertise (onboarding uses it). The target is
	// always the token caller — the request carries no member_id (identity comes
	// from the auth token, never a request field). Contrast AssignRole, which is
	// org-admin gated and targets another member on one project.
	SetOwnExpertise(context.Context, *connect.Request[v1.SetOwnExpertiseRequest]) (*connect.Response[v1.SetOwnExpertiseResponse], error)
	// --- MCP connections (OAuth-issued, per grant_id) ---
	// ListMcpConnections returns the caller's connected MCP clients: one entry
	// per grant_id (an access+refresh pair and every pair produced by rotating
	// it), never the tokens themselves.
	ListMcpConnections(context.Context, *connect.Request[v1.ListMcpConnectionsRequest]) (*connect.Response[v1.ListMcpConnectionsResponse], error)
	// RevokeMcpConnection disconnects one of the caller's MCP clients
	// immediately: every token sharing the grant is revoked in one call.
	RevokeMcpConnection(context.Context, *connect.Request[v1.RevokeMcpConnectionRequest]) (*connect.Response[v1.RevokeMcpConnectionResponse], error)
	// --- Machine tokens (phase 1): non-interactive, admin-minted long-lived
	// tokens for a headless agent — no browser, no consent screen. ---
	// CreateMachineToken mints a durable access token scoped to project_ids
	// (org-admin only). The raw secret is returned exactly once, here — it is
	// never re-readable via ListMachineTokens.
	CreateMachineToken(context.Context, *connect.Request[v1.CreateMachineTokenRequest]) (*connect.Response[v1.CreateMachineTokenResponse], error)
	// ListMachineTokens returns the caller's minted machine tokens: metadata
	// only (org-admin only), never the secret or its hash.
	ListMachineTokens(context.Context, *connect.Request[v1.ListMachineTokensRequest]) (*connect.Response[v1.ListMachineTokensResponse], error)
	// RevokeMachineToken immediately invalidates one of the caller's machine
	// tokens (org-admin only).
	RevokeMachineToken(context.Context, *connect.Request[v1.RevokeMachineTokenRequest]) (*connect.Response[v1.RevokeMachineTokenResponse], error)
	// --- Presence (connection heartbeat) ---
	Heartbeat(context.Context, *connect.Request[v1.HeartbeatRequest]) (*connect.Response[v1.HeartbeatResponse], error)
	// --- Admin (RBAC-gated to lead/admin) ---
	// CreateOrganization creates an org with a global project and makes the caller
	// the org admin. Gated to any authenticated account (AccountID present in token);
	// no project RBAC required because the caller has no org/member yet.
	CreateOrganization(context.Context, *connect.Request[v1.CreateOrganizationRequest]) (*connect.Response[v1.CreateOrganizationResponse], error)
	CreateProject(context.Context, *connect.Request[v1.CreateProjectRequest]) (*connect.Response[v1.CreateProjectResponse], error)
	// Project management (org-admin only). Rename; archive is a reversible freeze
	// (data kept, routing stops); delete is a guarded hard delete;
	// ListProjectsDetailed backs the Projects tab.
	RenameProject(context.Context, *connect.Request[v1.RenameProjectRequest]) (*connect.Response[v1.RenameProjectResponse], error)
	SetProjectArchived(context.Context, *connect.Request[v1.SetProjectArchivedRequest]) (*connect.Response[v1.SetProjectArchivedResponse], error)
	DeleteProject(context.Context, *connect.Request[v1.DeleteProjectRequest]) (*connect.Response[v1.DeleteProjectResponse], error)
	// DeleteConversation hard-deletes a conversation and everything derived from
	// it (messages, candidates, delivery ledger, and its distilled KB entry).
	// Org-admin only, scoped to the caller's own org. Irreversible.
	DeleteConversation(context.Context, *connect.Request[v1.DeleteConversationRequest]) (*connect.Response[v1.DeleteConversationResponse], error)
	ListProjectsDetailed(context.Context, *connect.Request[v1.ListProjectsDetailedRequest]) (*connect.Response[v1.ListProjectsDetailedResponse], error)
	AddMember(context.Context, *connect.Request[v1.AddMemberRequest]) (*connect.Response[v1.AddMemberResponse], error)
	// InviteMembers invites a list of emails to a project in one call (org-admin).
	// Each email defaults to member role; per-email status is reported back.
	InviteMembers(context.Context, *connect.Request[v1.InviteMembersRequest]) (*connect.Response[v1.InviteMembersResponse], error)
	AssignRole(context.Context, *connect.Request[v1.AssignRoleRequest]) (*connect.Response[v1.AssignRoleResponse], error)
	RemoveMember(context.Context, *connect.Request[v1.RemoveMemberRequest]) (*connect.Response[v1.RemoveMemberResponse], error)
	// ListMembers returns the org roster (org-admin only): one rich record per
	// member with identity, channel + bindings, status, availability, org-admin
	// flag and per-project expertise. Backs the Team list + Edit Person views.
	ListMembers(context.Context, *connect.Request[v1.ListMembersRequest]) (*connect.Response[v1.ListMembersResponse], error)
	// GetOrgMember returns one member's full record by id (org-admin only).
	GetOrgMember(context.Context, *connect.Request[v1.GetOrgMemberRequest]) (*connect.Response[v1.GetOrgMemberResponse], error)
	// SetMemberAvailability flips a member between active and on_leave (org-admin
	// only). on_leave keeps the seat but stops routing; return_date is a display
	// reminder. The agent must not route to an on_leave member.
	SetMemberAvailability(context.Context, *connect.Request[v1.SetMemberAvailabilityRequest]) (*connect.Response[v1.SetMemberAvailabilityResponse], error)
	// SetMemberActivation deactivates or reactivates a member (org-admin only).
	// Deactivation removes them from billing (seat recount, prorated) and stops
	// routing; it is reversible.
	SetMemberActivation(context.Context, *connect.Request[v1.SetMemberActivationRequest]) (*connect.Response[v1.SetMemberActivationResponse], error)
	// SetOrgAdmin grants or revokes org-admin on another member (org-admin only).
	// Revoking the last remaining admin is refused.
	SetOrgAdmin(context.Context, *connect.Request[v1.SetOrgAdminRequest]) (*connect.Response[v1.SetOrgAdminResponse], error)
	// SyncChatDirectory backfills Slack ids for a project's already-invited
	// members by resolving each unbound member's email against the org's Slack
	// workspace. Org-admin only, project-scoped. Best-effort; reports counts.
	SyncChatDirectory(context.Context, *connect.Request[v1.SyncChatDirectoryRequest]) (*connect.Response[v1.SyncChatDirectoryResponse], error)
	// ConfigureProvider sets the messaging provider for a project.
	// Admin-only: the caller must hold the lead or admin role.
	// kind must be one of "slack", "teams", or "telegram".
	// Credentials are provider-specific key/value pairs (never returned by any RPC).
	ConfigureProvider(context.Context, *connect.Request[v1.ConfigureProviderRequest]) (*connect.Response[v1.ConfigureProviderResponse], error)
	// DisconnectProvider removes a project's messaging provider (credentials +
	// alert channels). Admin-only. Idempotent: disconnecting an absent provider
	// succeeds.
	DisconnectProvider(context.Context, *connect.Request[v1.DisconnectProviderRequest]) (*connect.Response[v1.DisconnectProviderResponse], error)
	// SendProviderTest sends a real test message through a configured provider —
	// a DM to the caller and a post to each configured alert channel — and
	// returns a per-target result so an admin sees exactly what works and what
	// fails (e.g. "the bot is not in that channel's server"). Org-admin only.
	SendProviderTest(context.Context, *connect.Request[v1.SendProviderTestRequest]) (*connect.Response[v1.SendProviderTestResponse], error)
	// Organization escalation settings (org-admin gated). Zero disables a rule;
	// an unset value falls back to the product default.
	GetOrganizationSettings(context.Context, *connect.Request[v1.GetOrganizationSettingsRequest]) (*connect.Response[v1.GetOrganizationSettingsResponse], error)
	UpdateOrganizationSettings(context.Context, *connect.Request[v1.UpdateOrganizationSettingsRequest]) (*connect.Response[v1.UpdateOrganizationSettingsResponse], error)
	// RenameOrganization renames the caller's organization (org-admin gated). The
	// org is resolved from the auth token, never a request field — the body
	// carries only the new name.
	RenameOrganization(context.Context, *connect.Request[v1.RenameOrganizationRequest]) (*connect.Response[v1.RenameOrganizationResponse], error)
	// DeleteOrganization hard-deletes the caller's organization and ALL its data
	// (projects, conversations, messages, members, providers, join codes) in one
	// atomic cascade. Org-admin gated; the org is resolved from the auth token,
	// never a request field. confirm_name must match the org's current name (a
	// typed-name guard against accidental deletion). Irreversible.
	DeleteOrganization(context.Context, *connect.Request[v1.DeleteOrganizationRequest]) (*connect.Response[v1.DeleteOrganizationResponse], error)
	// GetOrganization returns the caller's organization identity (id + name) so
	// the dashboard can show the real org name instead of a placeholder.
	GetOrganization(context.Context, *connect.Request[v1.GetOrganizationRequest]) (*connect.Response[v1.GetOrganizationResponse], error)
	// ListOrganizations returns every organization the caller participates in
	// (has at least one project in), so the dashboard can offer an org switcher.
	// The caller selects an active org by sending its id in the Orako-Org-Id
	// request header; the server honors it only for orgs the caller belongs to.
	ListOrganizations(context.Context, *connect.Request[v1.ListOrganizationsRequest]) (*connect.Response[v1.ListOrganizationsResponse], error)
	// --- Org join code (shareable self-serve join, org-admin gated) ---
	// GenerateJoinCode rotates the org's shareable join code: it revokes any prior
	// live code and returns a fresh one scoped to a project (project_id, or the
	// org's default project when empty). Someone who redeems the code at the MCP
	// OAuth consent screen self-provisions as a pending member.
	GenerateJoinCode(context.Context, *connect.Request[v1.GenerateJoinCodeRequest]) (*connect.Response[v1.GenerateJoinCodeResponse], error)
	// GetJoinCode returns the org's current live join code, or an inactive result
	// (active=false, empty code) when none exists so the UI shows "no code yet".
	GetJoinCode(context.Context, *connect.Request[v1.GetJoinCodeRequest]) (*connect.Response[v1.GetJoinCodeResponse], error)
	// RevokeJoinCode revokes the org's live join code. Idempotent.
	RevokeJoinCode(context.Context, *connect.Request[v1.RevokeJoinCodeRequest]) (*connect.Response[v1.RevokeJoinCodeResponse], error)
}

